"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-scroll-area";
export const scrollAreaVariants = cva(
  "v-scroll [overflow:auto] [max-height:var(--h,240px)] [padding:6px_6px_6px_18px] [border-radius:20px] [box-shadow:inset_0_0_0_1px_var(--v-border)] [background:var(--v-canvas)] [padding-right:4px]",
  {
    variants: { variant: { default: "", ink: "-ink" } },
    defaultVariants: { variant: "default" },
  },
);
export type ScrollAreaProps = React.ComponentProps<typeof Primitive.Root> &
  VariantProps<typeof scrollAreaVariants> & { viewportClassName?: string };
export function ScrollArea({
  className,
  variant,
  children,
  viewportClassName,
  ...props
}: ScrollAreaProps) {
  return (
    <Primitive.Root
      data-slot="scroll-area"
      data-part="root"
      className={cn(scrollAreaVariants({ variant }), className)}
      {...props}
    >
      <Primitive.Viewport
        data-slot="scroll-area-viewport"
        data-part="viewport"
        className={cn(
          "size-full rounded-[inherit] max-h-[var(--h,240px)]",
          viewportClassName,
        )}
      >
        {children}
      </Primitive.Viewport>
      <ScrollBar />
      <Primitive.Corner data-slot="scroll-area-corner" />
    </Primitive.Root>
  );
}
export type ScrollBarProps = React.ComponentProps<typeof Primitive.Scrollbar>;
export function ScrollBar({
  className,
  orientation = "vertical",
  ...props
}: ScrollBarProps) {
  return (
    <Primitive.Scrollbar
      data-slot="scroll-area-scrollbar"
      orientation={orientation}
      className={cn(
        "flex touch-none select-none",
        orientation === "vertical" ? "h-full w-3 p-1" : "h-3 flex-col p-1",
        className,
      )}
      {...props}
    >
      <Primitive.Thumb
        data-slot="scroll-area-thumb"
        data-part="thumb"
        className="relative flex-1 rounded-full bg-[color-mix(in_oklab,var(--v-ink)_34%,transparent)]"
      />
    </Primitive.Scrollbar>
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar-thumb {
  background: var(--v-border);
  border-radius: 3px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink::-webkit-scrollbar-thumb {
  background: rgba(251, 244, 230, 0.5);
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]).-ink {
  color: var(--v-on-ink);
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]) {
  scrollbar-gutter: stable;
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]) {
  scrollbar-gutter: stable;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ):hover::-webkit-scrollbar-track {
  background: color-mix(in oklab, var(--v-pink) 22%, transparent);
  border: 4px solid transparent;
  background-clip: content-box;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ):hover::-webkit-scrollbar-thumb {
  background: var(--v-ink);
  background-clip: content-box;
  border-width: 3px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar-thumb:hover {
  background: var(--v-brand);
  background-clip: content-box;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar-thumb:active {
  background: var(--v-pink-deep);
  background-clip: content-box;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink::-webkit-scrollbar-thumb {
  background: rgba(251, 244, 230, 0.5);
  background-clip: content-box;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink:hover::-webkit-scrollbar-thumb {
  background: var(--v-canvas);
  background-clip: content-box;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink::-webkit-scrollbar-thumb:hover {
  background: var(--v-pink);
  background-clip: content-box;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink:hover::-webkit-scrollbar-track {
  background: rgba(251, 244, 230, 0.1);
  border: 4px solid transparent;
  background-clip: content-box;
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]).v-card {
  padding: 6px 6px 6px 18px;
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]) > p,
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"])
  > .v-body {
  padding: 10px 0;
  border-bottom: 1px solid color-mix(in oklab, var(--v-border) 70%, transparent);
  font-size: 14.5px;
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"])
  > p:last-child {
  border-bottom: 0;
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]).-ink
  > p {
  border-bottom-color: rgba(251, 244, 230, 0.12);
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )[data-scrollable] {
  -webkit-mask-image: linear-gradient(
    to bottom,
    var(--mask-ink) 0,
    var(--mask-ink) calc(100% - 28px),
    color-mix(in oklab, var(--mask-ink) 20%, transparent) 100%
  );
  mask-image: linear-gradient(
    to bottom,
    var(--mask-ink) 0,
    var(--mask-ink) calc(100% - 28px),
    color-mix(in oklab, var(--mask-ink) 20%, transparent) 100%
  );
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )[data-scrollable="end"] {
  -webkit-mask-image: none;
  mask-image: none;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar-track {
  background: transparent;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-edge) 55%, transparent);
  border: 2px solid transparent;
  background-clip: content-box;
  border-radius: 999px;
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink::-webkit-scrollbar-thumb {
  background: rgba(251, 244, 230, 0.4);
  background-clip: content-box;
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]) {
  scrollbar-gutter: stable;
}
@supports not selector(::-webkit-scrollbar) {
  .v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]).-ink {
    scrollbar-color: rgba(251, 244, 230, 0.5) transparent;
  }
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink::-webkit-scrollbar-thumb {
  background-color: rgba(251, 244, 230, 0.42);
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink:hover::-webkit-scrollbar-thumb {
  background-color: rgba(251, 244, 230, 0.7);
}
.v-scroll:where(
    [data-slot="scroll-area"],
    [data-slot^="scroll-area-"]
  ).-ink::-webkit-scrollbar-thumb:hover {
  background-color: var(--v-pink);
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]) {
  scrollbar-gutter: stable;
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]) > p,
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"])
  > .v-body {
  margin-right: 6px;
}
:root[data-mode="dark"]
  .v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]) {
  background: var(--v-beige);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
:root[data-mode="dark"]
  .v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]).-ink {
  color: var(--v-text);
  box-shadow: inset 0 0 0 1px var(--v-border);
}
.v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]).-ink {
  background: var(--v-ink);
}
:root[data-mode="dark"]
  .v-scroll:where([data-slot="scroll-area"], [data-slot^="scroll-area-"]).-ink {
  background: var(--v-canvas);
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="scroll-area"],
  [data-slot^="scroll-area-"],
  [data-slot="scroll-area"]::before,
  [data-slot="scroll-area"]::after,
  [data-slot^="scroll-area-"]::before,
  [data-slot^="scroll-area-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

/* The viewport is Radix's scroll owner; content keeps the reference's direct-child rhythm. */
[data-slot="scroll-area"] {
  overflow: hidden;
}
[data-slot="scroll-area-viewport"] {
  max-height: calc(var(--h, 240px) - 12px);
}
[data-slot="scroll-area-viewport"] > div > :is(p, .v-body) {
  padding: 10px 0;
  margin-right: 6px;
  border-bottom: 1px solid color-mix(in oklab, var(--v-border) 70%, transparent);
  font-size: 14.5px;
}
[data-slot="scroll-area-viewport"] > div > p:last-child {
  border-bottom: 0;
}
[data-slot="scroll-area"].-ink [data-slot="scroll-area-viewport"] > div > p {
  border-bottom-color: rgba(251, 244, 230, 0.12);
}
[data-slot="scroll-area-scrollbar"][data-orientation="vertical"] {
  width: 8px;
  padding: 2px;
}
[data-slot="scroll-area-scrollbar"][data-orientation="horizontal"] {
  height: 8px;
  padding: 2px;
}
[data-slot="scroll-area-thumb"] {
  background: color-mix(in oklab, var(--v-edge) 55%, transparent);
}
[data-slot="scroll-area"].-ink [data-slot="scroll-area-thumb"] {
  background: rgba(251, 244, 230, 0.42);
}
[data-slot="scroll-area"].-ink:hover [data-slot="scroll-area-thumb"] {
  background: rgba(251, 244, 230, 0.7);
}
[data-slot="scroll-area"].-ink [data-slot="scroll-area-thumb"]:hover {
  background: var(--v-pink);
}

}
